sql_query:
SELECT COUNT(*) AS in_progress_batches
FROM "acme-chatbot"."batch-and-packing-tracker"
WHERE dispatch_date_time IS NULL;

SELECT COUNT(*) AS pending_quality_batches
FROM "acme-chatbot"."batch-and-packing-tracker"
WHERE quality IS NULL;

SELECT batch, fg_code, prod_desc
FROM "acme-chatbot"."batch-and-packing-tracker"
WHERE dispatch_date_time IS NOT NULL AND receipt_at_ev_date_time IS NULL;

SELECT batch, fg_code, prod_desc
FROM "acme-chatbot"."batch-and-packing-tracker"
WHERE critical_sku = 'Yes' AND dispatch_date_time IS NULL;

SELECT material, prod_desc, demand_3m, shipped_3m
FROM "acme-chatbot"."demand-forecast"
WHERE demand_3m > 0 AND (shipped_3m IS NULL OR shipped_3m = 0);

SELECT 
  ROUND(SUM(shipped_3m::bigint) * 100.0 / NULLIF(SUM(demand_3m::bigint), 0), 2) AS overall_fill_rate_percent
FROM "acme-chatbot"."demand-forecast";

SELECT COUNT(*) AS demand_gt_dispense
FROM "acme-chatbot"."material-packing-tracker"
WHERE demand_qty > dispense_qty;

SELECT mat_category, AVG(dispense_qty) AS avg_dispense_qty
FROM "acme-chatbot"."material-packing-tracker"
GROUP BY mat_category;

SELECT COUNT(*) AS full_loss_shipments
FROM "acme-chatbot".otif
WHERE in_full_loss = 1;

SELECT blending_code, SUM(dispense_qty) AS total_dispense
FROM "acme-chatbot"."material-packing-tracker"
GROUP BY blending_code;

SELECT AVG(demand_qty) AS avg_demand_high_priority
FROM "acme-chatbot"."material-packing-tracker"
WHERE priority >= 3;

SELECT shipping_point, AVG(so_recp_to_act_shp_days) AS avg_days
FROM "acme-chatbot".otif
GROUP BY shipping_point;
